    "category": "Política",
    "ingestedAt": "30/10/2026 às 16:39",
    "imageUrl": "https://imagens.ebc.com.br/fXmgHs6L2UzfwFAEnR7GT-Xu_vQ=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/atoms/image/994352-sp_05012016-05012016_abr8862-.jpg?itok=ZStJZ7yE",
    "imageCaption": "Polícia de SP investiga venda de dados de mortos a funerárias",
